package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type AmtRec struct {
	ArAcct string
	ArAmt  decimal.Decimal
}

var WsEofFlag string = "N"
var WsBigTotal decimal.Decimal = decimal.NewFromInt(0)
var WsWrapTotal decimal.Decimal = decimal.NewFromInt(0)
var WsSafeTotal decimal.Decimal = decimal.NewFromInt(0)
var WsOverflows int64 = 0
var WsCount int64 = 0
var WsHalf decimal.Decimal = decimal.NewFromInt(0)
var WsAmtEd string
var WsWrapEd string
var WsSafeEd string
var WsHalfEd string

var amtFileLines []string
var amtFileIndex int
var currentAmtRec AmtRec

func main() {
	// OPEN INPUT AMT-FILE is simulated by reading input.dat
	f, err := os.Open("input.dat")
	if err != nil {
		// if file does not exist treat as empty (COBOL would error, but keep)
		amtFileLines = []string{}
	} else {
		scanner := bufio.NewScanner(f)
		for scanner.Scan() {
			line := scanner.Text()
			// scanner strips newline, we keep line as is
			// COBOL LINE SEQUENTIAL: keep content without newline
			amtFileLines = append(amtFileLines, line)
		}
		f.Close()
	}
	amtFileIndex = 0

	MAIN_PARA()
}

func MAIN_PARA() {
	// OPEN INPUT already done
	READ_PARA()
	for !isInputDone() {
		PROCESS_PARA()
	}
	// CLOSE
	SUMMARY_PARA()
}

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func READ_PARA() {
	if amtFileIndex >= len(amtFileLines) {
		WsEofFlag = "Y"
		return
	}
	raw := amtFileLines[amtFileIndex]
	amtFileIndex++
	// pad to 11
	if len(raw) < 11 {
		raw = raw + strings.Repeat(" ", 11-len(raw))
	} else if len(raw) > 11 {
		raw = raw[:11]
	}
	arAcct := raw[0:4]
	arAmtStr := raw[4:11] // 7 chars
	amtVal := parsePic9V99_5_2(arAmtStr)
	currentAmtRec = AmtRec{ArAcct: arAcct, ArAmt: amtVal}
}

func parsePic9V99_5_2(s string) decimal.Decimal {
	// digits only, implied 2 decimals
	trimmed := strings.TrimSpace(s)
	if trimmed == "" {
		return decimal.NewFromInt(0)
	}
	// keep only digits, ignoring other chars
	// spec says digits only, but be safe
	var digits strings.Builder
	for _, ch := range trimmed {
		if ch >= '0' && ch <= '9' {
			digits.WriteRune(ch)
		}
	}
	ds := digits.String()
	if ds == "" {
		return decimal.NewFromInt(0)
	}
	// ds may be shorter than 7 if file omitted leading zeros, treat as numeric value
	// But PIC 9(5)V99 with 7 chars zero padded: parsing as integer then scale -2 yields correct
	// If string length <7 but represents same digits left-padded with zero, integer value same.
	n, _ := decimal.NewFromString(ds)
	// n is integer of digits
	return decimal.New(n.IntPart(), -2)
}

// helpers for COBOL storage semantics

func pow10(n int) int64 {
	var p int64 = 1
	for i := 0; i < n; i++ {
		p *= 10
	}
	return p
}

func storeDecimal(value decimal.Decimal, intDigits int, scale int) decimal.Decimal {
	// truncate to scale toward zero before wrapping (value should already be at that scale,
	// but ensure)
	v := value.Truncate(int32(scale))
	// scaled integer
	// scaled = v * 10^scale
	shifted := v.Shift(int32(scale)) // multiply by 10^scale
	// shifted is integer decimal (scale 0)
	// modulo totalDigits = intDigits+scale
	totalDigits := intDigits + scale
	modulus := decimal.NewFromInt(pow10(totalDigits))
	// need positive modulo keeping sign? For positive values modulo is simple.
	// For negative values COBOL would keep sign? Not needed (all positive).
	// Use truncated toward zero integer value
	// shifted may be negative; compute low-order digits modulo with sign preservation
	// Approach: get integer part as int64 (fits within 9 digits), do modulo
	// Use decimal Mod with positive modulus then reapply sign
	isNeg := shifted.IsNegative()
	absShifted := shifted.Abs()
	// absShifted % modulus
	// modulus fits int64 up to 1e9, safe
	mod := absShifted.Mod(modulus)
	if isNeg {
		mod = mod.Neg()
	}
	// divide back
	result := mod.Shift(int32(-scale))
	// ensure scale
	result = result.Truncate(int32(scale))
	return result
}

func fitsInPic(value decimal.Decimal, intDigits int, scale int) bool {
	// check if value can be represented without overflow
	// value is truncated to scale (COBOL would truncate result before checking? For ADD, result before storing)
	// overflow if absolute integer part >= 10^intDigits
	v := value.Truncate(int32(scale))
	if v.IsNegative() {
		v = v.Abs()
	}
	// threshold = 10^intDigits
	threshold := decimal.NewFromInt(pow10(intDigits))
	// need v < threshold (since max is 10^intDigits - 10^-scale)
	return v.LessThan(threshold)
}

// editing

func formatEdited(value decimal.Decimal, picture string) string {
	// picture like "ZZ,ZZ9.99"
	n := len(picture)
	out := make([]rune, n)
	for i, ch := range picture {
		out[i] = ch
	}
	// find dot
	dotIdx := strings.Index(picture, ".")
	var intPic, fracPic string
	if dotIdx >= 0 {
		intPic = picture[:dotIdx]
		fracPic = picture[dotIdx+1:]
	} else {
		intPic = picture
		fracPic = ""
	}
	intCap := 0
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			intCap++
		}
	}
	fracCap := 0
	for _, ch := range fracPic {
		if ch == 'Z' || ch == '9' {
			fracCap++
		}
	}
	// compute intPart and fracPart
	absVal := value.Abs()
	// integer part truncated toward zero
	intPartDec := absVal.Truncate(0)
	intPartInt := intPartDec.IntPart() // fits
	var powIntCap int64 = 1
	for i := 0; i < intCap; i++ {
		powIntCap *= 10
	}
	intMod := intPartInt % powIntCap
	if intMod < 0 {
		intMod = -intMod
	}
	intDigits := make([]int, intCap)
	tmp := intMod
	for i := intCap - 1; i >= 0; i-- {
		intDigits[i] = int(tmp % 10)
		tmp /= 10
	}
	// fractional part: fracCap digits
	fracDigits := make([]int, fracCap)
	if fracCap > 0 {
		fracDec := absVal.Sub(intPartDec) // 0 <= <1
		// multiply by 10^fracCap
		mult := decimal.NewFromInt(pow10(fracCap))
		fracShifted := fracDec.Mul(mult).Truncate(0)
		fracInt := fracShifted.IntPart()
		if fracInt < 0 {
			fracInt = -fracInt
		}
		tmp2 := fracInt
		for i := fracCap - 1; i >= 0; i-- {
			fracDigits[i] = int(tmp2 % 10)
			tmp2 /= 10
		}
	}
	// Map digit positions
	// Build list of positions for int digits in order
	type slot struct {
		picIdx int
		isZ    bool
	}
	var intSlots []slot
	for idx, ch := range picture {
		if dotIdx >= 0 && idx > dotIdx {
			break
		}
		if ch == 'Z' || ch == '9' {
			intSlots = append(intSlots, slot{picIdx: idx, isZ: ch == 'Z'})
		}
	}
	var fracSlots []slot
	if dotIdx >= 0 {
		for idx, ch := range picture {
			if idx <= dotIdx {
				continue
			}
			if ch == 'Z' || ch == '9' {
				fracSlots = append(fracSlots, slot{picIdx: idx, isZ: ch == 'Z'})
			}
		}
	}
	// Determine first non-zero in intDigits
	firstNZ := -1
	for i, d := range intDigits {
		if d != 0 {
			firstNZ = i
			break
		}
	}
	// Fill int slots
	for i, sl := range intSlots {
		d := intDigits[i]
		var ch rune
		if firstNZ == -1 {
			// all zero
			if sl.isZ {
				ch = ' '
			} else {
				ch = rune('0' + d)
			}
		} else {
			if i < firstNZ {
				// leading zero before first non-zero
				if sl.isZ {
					ch = ' '
				} else {
					// 9 slot before firstNZ should still be digit? But in this picture the only 9 is last, so not reached.
					ch = rune('0' + d)
				}
			} else {
				ch = rune('0' + d)
			}
		}
		out[sl.picIdx] = ch
	}
	// fill frac slots
	for i, sl := range fracSlots {
		d := fracDigits[i]
		out[sl.picIdx] = rune('0' + d)
	}
	// handle commas that are in suppressed zone -> become space
	// For each comma in picture, if all intSlots to its left are suppressed (space), then comma -> space
	for idx, ch := range picture {
		if ch != ',' {
			continue
		}
		// determine if comma is in integer part (before dot)
		if dotIdx >= 0 && idx > dotIdx {
			continue
		}
		// look at intSlots with picIdx < idx
		allSuppressed := true
		anyLeft := false
		for _, sl := range intSlots {
			if sl.picIdx < idx {
				anyLeft = true
				if out[sl.picIdx] != ' ' {
					allSuppressed = false
					break
				}
			}
		}
		// Also need at least one left slot; if no left slots ambiguous, keep comma? Not needed.
		if anyLeft && allSuppressed {
			out[idx] = ' '
		} else {
			out[idx] = ','
		}
	}
	// dot stays '.'
	return string(out)
}

func formatPic99(v int64) string {
	// PIC 99 zero-padded width 2 modulus 100
	// value already wrapped to 0..99? but v may be >99 if not wrapped? We wrap as per store
	mod := v % 100
	if mod < 0 {
		mod = -mod
	}
	return fmt.Sprintf("%02d", mod)
}

func PROCESS_PARA() {
	// ADD AR-AMT TO WS-BIG-TOTAL
	sumBig := WsBigTotal.Add(currentAmtRec.ArAmt)
	WsBigTotal = storeDecimal(sumBig, 7, 2)

	// MOVE WS-BIG-TOTAL TO WS-WRAP-TOTAL
	WsWrapTotal = storeDecimal(WsBigTotal, 5, 2)

	// ADD AR-AMT TO WS-SAFE-TOTAL ON SIZE ERROR PERFORM OVERFLOW-PARA END-ADD
	sumSafe := WsSafeTotal.Add(currentAmtRec.ArAmt)
	sumSafeTrunc := sumSafe.Truncate(2)
	if fitsInPic(sumSafeTrunc, 5, 2) {
		WsSafeTotal = storeDecimal(sumSafeTrunc, 5, 2)
	} else {
		OVERFLOW_PARA()
	}

	// ADD 1 TO WS-COUNT
	WsCount = WsCount + 1
	// wrap per PIC 99
	WsCount = WsCount % 100

	// COMPUTE WS-HALF = AR-AMT / 2 (truncated)
	// halfExact = AR-AMT *5 /10  exact
	halfExact := currentAmtRec.ArAmt.Mul(decimal.NewFromInt(5)).Shift(-1)
	halfTrunc := halfExact.Truncate(1)
	WsHalf = storeDecimal(halfTrunc, 5, 1)

	// MOVE to edited
	WsAmtEd = formatEdited(currentAmtRec.ArAmt, "ZZ,ZZ9.99")
	WsWrapEd = formatEdited(WsWrapTotal, "ZZ,ZZ9.99")
	WsSafeEd = formatEdited(WsSafeTotal, "ZZ,ZZ9.99")
	WsHalfEd = formatEdited(WsHalf, "ZZ,ZZ9.9")

	// DISPLAY
	// AR-ACCT is X(4) exactly 4 chars
	fmt.Printf("%s %s %s %s %s\n", currentAmtRec.ArAcct, WsAmtEd, WsWrapEd, WsSafeEd, WsHalfEd)

	READ_PARA()
}

func SUMMARY_PARA() {
	fmt.Printf("RECORDS: %s\n", formatPic99(WsCount))
	fmt.Printf("OVERFLOWS: %s\n", formatPic99(WsOverflows))
}

func OVERFLOW_PARA() {
	WsOverflows = WsOverflows + 1
	WsOverflows = WsOverflows % 100
}
